import React, { useState } from "react";

const Quiz = ({ onSubmit }) => {
  const [style, setStyle] = useState("");
  const [occasion, setOccasion] = useState("");

  const outfitSuggestions = {
    Classic: {
      Work: "Blazer + trousers, button-down shirt",
      Party: "Midi dress, subtle jewelry",
      Casual: "White tee + jeans, loafers",
      Vacation: "Linen pants + tank, straw accessories",
    },
    Boho: {
      Work: "Flowy blouse + wide-leg pants",
      Party: "Embroidered kurta set, tribal jewelry",
      Casual: "Maxi dress, denim jacket, sandals",
      Vacation: "Flared skirt, crop top, woven tote",
    },
    Chic: {
      Work: "Monochrome suit, statement heels",
      Party: "Co-ord set, sleek bun, bold lip",
      Casual: "Pleated skirt, structured top, clutch",
      Vacation: "Matching sets, gold jewelry, sunglasses",
    },
    Streetwear: {
      Work: "Oversized blazer + joggers, edgy sneakers",
      Party: "Graphic tee, mini skirt, platforms",
      Casual: "Cargo pants, oversized tee, cap",
      Vacation: "Hoodie dress, crossbody bag, slides",
    },
  };

  const selectedOutfit = style && occasion
    ? `Your **${style}** style outfit for **${occasion}**: ${outfitSuggestions[style]?.[occasion] || "No suggestion found"}`
    : "Choose your style and occasion to see an outfit idea.";

  const handleSubmit = (e) => {
    e.preventDefault();
    onSubmit({ style, occasion });
  };

  return (
    <form onSubmit={handleSubmit} style={{ maxWidth: "500px", margin: "0 auto", textAlign: "left" }}>
      <h1>👗 MyStyleDNA Quiz</h1>

      {/* Style */}
      <label>✨ Your Style:</label>
      <select value={style} onChange={(e) => setStyle(e.target.value)} required>
        <option value="">-- Choose Style --</option>
        <option value="Classic">Classic</option>
        <option value="Boho">Boho</option>
        <option value="Chic">Chic</option>
        <option value="Streetwear">Streetwear</option>
      </select>

      <br /><br />

      {/* Occasion */}
      <label>🎯 Occasion:</label>
      <select value={occasion} onChange={(e) => setOccasion(e.target.value)} required>
        <option value="">-- Choose Occasion --</option>
        <option value="Work">Work</option>
        <option value="Party">Party</option>
        <option value="Casual">Casual</option>
        <option value="Vacation">Vacation</option>
      </select>

      <br /><br />

      {/* Outfit Suggestion */}
      <div style={{ marginTop: "20px", padding: "10px", background: "#f7f7f7", borderRadius: "8px" }}>
        <strong>🪞 Outfit Suggestion:</strong>
        <p dangerouslySetInnerHTML={{ __html: selectedOutfit }} />
      </div>

      <br />
      <button
        type="submit"
        disabled={!style || !occasion}
        style={{ padding: "10px 20px", borderRadius: "6px", border: "1px solid #ccc", backgroundColor: "#f0f0f0", marginTop: "20px" }}
      >
        Show My Style
      </button>
    </form>
  );
};

export default Quiz;
